<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();$s=db()->prepare('SELECT r.reward_id,h.title hunt,r.amount,r.status,r.rejection_reason,r.created_at,r.decided_at FROM rewards r JOIN hunts h ON h.id=r.hunt_id WHERE r.user_id=? ORDER BY r.id DESC LIMIT 100');$s->execute([$user['id']]);json_response(true,'Rewards',['items'=>$s->fetchAll()]);
